// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(c.initialized() == false);

        // Seed the market first
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.seedMarket{value: 0.1 ether}(1000);

        // Now call getFreeKilo
        vm.prank(caller);
        c.getFreeKilo();

        // The assertion: lastCollect of the caller equals block.timestamp
        assertTrue(c.lastCollect(caller) == block.timestamp, "lastCollect should equal block.timestamp");
    }
}

